<?php
require __DIR__.'/src/bootstrap.php';
require_admin();
$defaults=['site_name'=>'نَسَق','site_tagline'=>'أعمالك بنسق مختلف','site_description'=>'منصة الأعمال والحلول الرقمية','contact_email'=>'','contact_phone'=>'','hero_title'=>'أفكار طموحة. تنفيذ بنسق مختلف.','hero_description'=>'منصة تجمع تطوير البرمجيات والحلول التقنية والمنتجات الرقمية في تجربة واحدة.'];
$error='';$success='';
try{$q=db()->query('SELECT setting_key,setting_value FROM site_settings');$settings=array_replace($defaults,$q->fetchAll(PDO::FETCH_KEY_PAIR));}catch(PDOException $e){http_response_code(503);exit('يلزم استيراد ملف database-upgrade-v2.sql من phpMyAdmin لتفعيل الإعدادات.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
verify_csrf();$action=$_POST['action']??'';
if($action==='settings'){
$values=[];foreach($defaults as $key=>$default){$values[$key]=trim((string)($_POST[$key]??''));if(mb_strlen($values[$key])>500){$error='تجاوز أحد الحقول الطول المسموح.';break;}}
if(!$error&&$values['site_name']==='')$error='اسم المنصة مطلوب.';
if(!$error&&$values['contact_email']!==''&&!filter_var($values['contact_email'],FILTER_VALIDATE_EMAIL))$error='البريد الإلكتروني غير صحيح.';
if(!$error){$stmt=db()->prepare('INSERT INTO site_settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $key=>$value)$stmt->execute([$key,$value]);$settings=$values;$success='تم حفظ إعدادات المنصة.';}
}elseif($action==='password'){
$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
$q=db()->prepare('SELECT password_hash FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$hash=$q->fetchColumn();
if(!$hash||!password_verify($old,$hash))$error='كلمة المرور الحالية غير صحيحة.';
elseif(strlen($new)<12||strlen($new)>128)$error='يجب أن تكون كلمة المرور الجديدة من 12 إلى 128 حرفًا.';
elseif($new!==$confirm)$error='تأكيد كلمة المرور غير مطابق.';
else{$q=db()->prepare('UPDATE admins SET password_hash=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);session_regenerate_id(true);$success='تم تغيير كلمة المرور بنجاح.';}
}}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap"><link rel="stylesheet" href="assets/style.css?v=3"><title>إعدادات نَسَق</title></head><body><header class="site-header"><nav class="wrap site-nav"><a class="brand" href="admin.php"><span class="brand-mark">ن</span><span>نَسَق<small>CONTROL CENTER</small></span></a><a class="btn secondary" href="admin.php">العودة للوحة التحكم</a></nav></header><main class="wrap admin-shell"><section class="pagehead"><span class="eyebrow">التحكم والإعدادات</span><h1>إعدادات المنصة</h1><p>إدارة الهوية والمعلومات الأساسية وأمان حساب المدير.</p></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice" role="status"><?=e($success)?></div><?php endif;?><div class="settings-grid"><section class="panel"><h2>هوية الموقع ومعلومات التواصل</h2><form method="post" class="settings-form"><?=csrf_field()?><input type="hidden" name="action" value="settings"><?php foreach(['site_name'=>'اسم المنصة','site_tagline'=>'الشعار النصي','site_description'=>'وصف المنصة','hero_title'=>'عنوان الرئيسية','hero_description'=>'وصف الرئيسية','contact_email'=>'البريد الرسمي','contact_phone'=>'رقم التواصل'] as $key=>$label):?><label><?=e($label)?><?php if(in_array($key,['hero_description','site_description'],true)):?><textarea name="<?=$key?>" maxlength="500" rows="3"><?=e($settings[$key])?></textarea><?php else:?><input name="<?=$key?>" maxlength="500" value="<?=e($settings[$key])?>" <?=$key==='site_name'?'required':''?> <?=$key==='contact_email'?'type="email"':''?>><?php endif;?></label><?php endforeach;?><button class="btn" type="submit">حفظ الإعدادات</button></form></section><section class="panel"><h2>أمان حساب المدير</h2><p class="muted">استخدم كلمة مرور طويلة وفريدة، ولا تشاركها مع أي شخص.</p><form method="post" class="settings-form"><?=csrf_field()?><input type="hidden" name="action" value="password"><label>كلمة المرور الحالية<input type="password" name="old_password" autocomplete="current-password" required></label><label>كلمة المرور الجديدة<input type="password" name="new_password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>تأكيد كلمة المرور<input type="password" name="confirm_password" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="btn" type="submit">تغيير كلمة المرور</button></form></section></div></main></body></html>